        campusAddress: `${city.name}${pickOne(["\u6559\u80B2\u8DEF", "\u6587\u6C47\u8DEF", "\u5B66\u9662\u8DEF", "\u4E66\u9999\u5927\u9053", "\u80B2\u624D\u8DEF"], random) || "\u6559\u80B2\u8DEF"}${serial % 180 + 18}\u53F7`,
