            sceneId: scene.id,
            sceneName: scene.sceneName,
            status: scene.status,
            tableCount: Number(scene.tableCount || 0),
            totalDataCount: Number(scene.totalDataCount || 0),
            topicCount: Number(topicSummary.topicCount || 0),
